"""Core earnings math for the commission-calculator skill.

This implements the deterministic formulas from ``SKILL.md`` Step 4 (Calculate
Monthly and Projected Earnings). It intentionally covers only the parts of the
skill that are pure calculation — fetching live program data from
``list.affitor.com`` (see ``references/list-affitor-api.md``) and traffic/CTR
benchmark selection are agent-side concerns and are supplied as inputs here.

All monetary results are rounded to cents so projections are presentable.
"""

from __future__ import annotations

# Scenario multipliers map to where inside a benchmark range to sample.
SCENARIOS = ("conservative", "realistic", "optimistic")


def parse_reward_value(reward_value: str) -> tuple[str, float]:
    """Parse a ``reward_value`` string into ``(kind, amount)``.

    Percentage rewards -> ``("percentage", 30.0)`` for ``"30%"``.
    Fixed rewards      -> ``("fixed", 50.0)`` for ``"$50"`` (``$`` and thousands
    separators are tolerated).
    """
    if not isinstance(reward_value, str):
        raise TypeError("reward_value must be a string like '30%' or '$50'")
    text = reward_value.strip()
    if text.endswith("%"):
        return "percentage", float(text[:-1].strip())
    cleaned = text.lstrip("$").replace(",", "").strip()
    return "fixed", float(cleaned)


def commission_per_sale(reward_value: str, avg_product_price: float | None = None) -> float:
    """Commission earned per converted sale, per SKILL Step 4.

    Percentage-based: ``avg_product_price * (reward_value / 100)``.
    Fixed: the reward value itself. ``avg_product_price`` is required for
    percentage rewards.
    """
    kind, amount = parse_reward_value(reward_value)
    if kind == "percentage":
        if avg_product_price is None:
            raise ValueError(
                "avg_product_price is required for percentage-based rewards"
            )
        return round(avg_product_price * amount / 100.0, 2)
    return round(amount, 2)


def monthly_conversions(monthly_visitors: float, ctr: float, conversion_rate: float) -> float:
    """Monthly conversions = visitors x click-through rate x conversion rate.

    ``ctr`` and ``conversion_rate`` are fractions (e.g. ``0.03`` for 3%).
    """
    return monthly_visitors * ctr * conversion_rate


def one_time_monthly_commission(
    monthly_visitors: float,
    ctr: float,
    conversion_rate: float,
    per_sale: float,
) -> float:
    """Month-1 (and steady) earnings for a one-time reward program."""
    conversions = monthly_conversions(monthly_visitors, ctr, conversion_rate)
    return round(conversions * per_sale, 2)


def recurring_monthly_projection(
    monthly_new_conversions: float,
    per_sale: float,
    months: int,
    duration_months: int | None = None,
) -> list[float]:
    """Per-month revenue for a recurring (subscription) program.

    Uses the compounding model from SKILL Step 4: every month adds a new cohort
    of subscribers that keeps paying ``per_sale`` each subsequent month. With no
    churn, month ``N`` earns from all still-active cohorts.

    ``duration_months`` caps how long each cohort keeps paying (e.g. 12 for a
    "12 months" reward_duration). ``None`` models a "lifetime" payout.
    Returns a list of length ``months`` (index 0 == month 1).
    """
    if months < 1:
        raise ValueError("months must be >= 1")
    if duration_months is not None and duration_months < 1:
        raise ValueError("duration_months must be >= 1 when provided")

    revenues: list[float] = []
    for n in range(1, months + 1):
        active_cohorts = n if duration_months is None else min(n, duration_months)
        active_subscribers = monthly_new_conversions * active_cohorts
        revenues.append(round(active_subscribers * per_sale, 2))
    return revenues


def cumulative(revenues: list[float]) -> float:
    """Total earnings across a list of monthly revenues."""
    return round(sum(revenues), 2)


def scenario_rate(low: float, high: float, scenario: str = "realistic") -> float:
    """Pick a rate from a benchmark ``[low, high]`` range per SKILL Step 3.

    conservative -> low bound, realistic -> midpoint, optimistic -> high bound.
    """
    if scenario not in SCENARIOS:
        raise ValueError(f"scenario must be one of {SCENARIOS}, got {scenario!r}")
    if scenario == "conservative":
        return low
    if scenario == "optimistic":
        return high
    return (low + high) / 2.0


def sales_needed_for_goal(goal_per_month: float, per_sale: float) -> float:
    """Sales/month required to reach an income goal (SKILL Step 6)."""
    if per_sale <= 0:
        raise ValueError("per_sale must be positive")
    return goal_per_month / per_sale


def visitors_needed_for_goal(
    goal_per_month: float,
    per_sale: float,
    ctr: float,
    conversion_rate: float,
) -> float:
    """Monthly visitors required to reach an income goal (SKILL Step 6)."""
    if ctr <= 0 or conversion_rate <= 0:
        raise ValueError("ctr and conversion_rate must be positive")
    needed_sales = sales_needed_for_goal(goal_per_month, per_sale)
    return needed_sales / (ctr * conversion_rate)
